create table if not exists public.inventory_movements(id uuid primary key default gen_random_uuid(),inventory_item_id uuid not null references public.inventory_items(id) on delete cascade,quantity_change numeric not null,quantity_before numeric not null,quantity_after numeric not null,movement_type text not null check(movement_type in('receive','use','adjustment','damage','waste','transfer_in','transfer_out','correction')),reason text,reference_id uuid,performed_by uuid references auth.users(id),created_at timestamptz not null default now());
alter table public.inventory_movements enable row level security;
drop policy if exists inventory_movements_owner_all on public.inventory_movements;
create policy inventory_movements_owner_all on public.inventory_movements for all to authenticated using(exists(select 1 from public.admin_user_roles r where r.user_id=auth.uid() and r.role='SUPER_ADMIN' and r.active)) with check(exists(select 1 from public.admin_user_roles r where r.user_id=auth.uid() and r.role='SUPER_ADMIN' and r.active));
create or replace function public.owner_adjust_inventory(p_item_id uuid,p_quantity_change numeric,p_movement_type text,p_reason text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare is_owner boolean; before_qty numeric; after_qty numeric; item_name text; begin select exists(select 1 from public.admin_user_roles r where r.user_id=auth.uid() and r.role='SUPER_ADMIN' and r.active) into is_owner; if not is_owner then raise exception 'Owner access required'; end if; if p_quantity_change=0 then raise exception 'Quantity change cannot be zero'; end if; if p_movement_type not in('receive','use','adjustment','damage','waste','transfer_in','transfer_out','correction') then raise exception 'Invalid movement type'; end if; select current_stock,name into before_qty,item_name from public.inventory_items where id=p_item_id and active=true for update; if not found then raise exception 'Inventory item not found'; end if; after_qty:=before_qty+p_quantity_change; if after_qty<0 then raise exception 'Inventory cannot go below zero'; end if; update public.inventory_items set current_stock=after_qty,updated_at=now() where id=p_item_id; insert into public.inventory_movements(inventory_item_id,quantity_change,quantity_before,quantity_after,movement_type,reason,performed_by) values(p_item_id,p_quantity_change,before_qty,after_qty,p_movement_type,p_reason,auth.uid()); return jsonb_build_object('item_id',p_item_id,'item_name',item_name,'quantity_before',before_qty,'quantity_after',after_qty,'quantity_change',p_quantity_change); end; $$; revoke all on function public.owner_adjust_inventory(uuid,numeric,text,text) from public,anon; grant execute on function public.owner_adjust_inventory(uuid,numeric,text,text) to authenticated;
create or replace function public.owner_inventory_dashboard() returns jsonb language plpgsql security definer set search_path=public as $$ declare is_owner boolean; result jsonb; begin select exists(select 1 from public.admin_user_roles r where r.user_id=auth.uid() and r.role='SUPER_ADMIN' and r.active) into is_owner; if not is_owner then raise exception 'Owner access required'; end if; select jsonb_build_object('summary',jsonb_build_object('total_items',(select count(*) from public.inventory_items where active),'low_stock',(select count(*) from public.inventory_items where active and current_stock<=minimum_stock),'out_of_stock',(select count(*) from public.inventory_items where active and current_stock<=0),'overstocked',(select count(*) from public.inventory_items where active and current_stock>greatest(maximum_stock,0) and maximum_stock>0)),'items',coalesce((select jsonb_agg(to_jsonb(x)) from(select i.id,i.name,i.category,i.unit,i.current_stock,i.minimum_stock,i.target_stock,i.maximum_stock,i.average_daily_usage,case when i.current_stock<=0 then 'out_of_stock' when i.current_stock<=i.minimum_stock then 'low' when i.maximum_stock>0 and i.current_stock>i.maximum_stock then 'overstocked' else 'healthy' end status,case when i.average_daily_usage>0 then round(i.current_stock/i.average_daily_usage,1) else null end estimated_days_remaining,case when i.current_stock<=i.minimum_stock then greatest(i.target_stock-i.current_stock,0) else 0 end recommended_order from public.inventory_items i where i.active order by case when i.current_stock<=0 then 1 when i.current_stock<=i.minimum_stock then 2 when i.maximum_stock>0 and i.current_stock>i.maximum_stock then 3 else 4 end,i.name)x),'[]'::jsonb),'recent_movements',coalesce((select jsonb_agg(to_jsonb(x)) from(select m.id,m.inventory_item_id,i.name,m.quantity_change,m.quantity_before,m.quantity_after,m.movement_type,m.reason,m.created_at from public.inventory_movements m join public.inventory_items i on i.id=m.inventory_item_id order by m.created_at desc limit 100)x),'[]'::jsonb)) into result; return result; end; $$; revoke all on function public.owner_inventory_dashboard() from public,anon; grant execute on function public.owner_inventory_dashboard() to authenticated;
create or replace function public.owner_create_inventory_item(p_name text,p_category text,p_unit text,p_minimum numeric,p_target numeric,p_maximum numeric default 0,p_daily_usage numeric default 0,p_initial_stock numeric default 0) returns uuid language plpgsql security definer set search_path=public as $$ declare is_owner boolean; new_id uuid; begin select exists(select 1 from public.admin_user_roles r where r.user_id=auth.uid() and r.role='SUPER_ADMIN' and r.active) into is_owner; if not is_owner then raise exception 'Owner access required'; end if; if coalesce(p_name,'')='' or coalesce(p_unit,'')='' then raise exception 'Name and unit are required'; end if; if p_minimum<0 or p_target<p_minimum or p_maximum<p_target or p_initial_stock<0 or p_daily_usage<0 then raise exception 'Invalid inventory thresholds'; end if; insert into public.inventory_items(name,category,unit,current_stock,minimum_stock,target_stock,maximum_stock,average_daily_usage,active) values(p_name,p_category,p_unit,p_initial_stock,p_minimum,p_target,p_maximum,p_daily_usage,true) returning id into new_id; if p_initial_stock>0 then insert into public.inventory_movements(inventory_item_id,quantity_change,quantity_before,quantity_after,movement_type,reason,performed_by) values(new_id,p_initial_stock,0,p_initial_stock,'receive','Initial inventory',auth.uid()); end if; return new_id; end; $$; revoke all on function public.owner_create_inventory_item(text,text,text,numeric,numeric,numeric,numeric,numeric) from public,anon; grant execute on function public.owner_create_inventory_item(text,text,text,numeric,numeric,numeric,numeric,numeric) to authenticated;
create or replace function public.sync_inventory_item_to_supply_item() returns trigger language plpgsql security definer set search_path=public as $$ begin if exists(select 1 from public.supply_items where lower(name)=lower(new.name)) then update public.supply_items set category=new.category,unit_label=new.unit,current_stock=new.current_stock,minimum_stock=new.minimum_stock,reorder_quantity=greatest(new.target_stock-new.current_stock,0),active=new.active,updated_at=now() where lower(name)=lower(new.name); else insert into public.supply_items(name,category,unit_label,current_stock,minimum_stock,reorder_quantity,active) values(new.name,new.category,new.unit,new.current_stock,new.minimum_stock,greatest(new.target_stock-new.current_stock,0),new.active); end if; return new; end; $$; drop trigger if exists trg_inventory_to_supply_item on public.inventory_items; create trigger trg_inventory_to_supply_item after insert or update of name,category,unit,current_stock,minimum_stock,target_stock,active on public.inventory_items for each row execute function public.sync_inventory_item_to_supply_item();
